INSERT INTO care_events (
  id, plant_id, household_id, care_type, performed_at, performed_by,
  quantity_ml, source, notes, pruning_kind
)
SELECT v.id,
       v.plant_id,
       p.household_id,
       v.care_type,
       (date_trunc('day', timezone('Europe/Warsaw', now()))
         - v.days_ago * interval '1 day'
         + v.hour_offset * interval '1 hour')
         AT TIME ZONE 'Europe/Warsaw',
       v.performed_by,
       v.quantity_ml,
